//! Replay the original public graph-planning driver against locked Rust v5.0.6.
//! Historical driver remains unchanged; new scoped inputs disable clock fields.
use std::{collections::{BTreeMap,BTreeSet},io::{self,BufRead},sync::{Arc,Mutex,atomic::{AtomicU64,Ordering}},future::Future,task::{Context,Poll,Wake,Waker}};
use serde_json::{json,Value as J};
use teaql_core::*;
use teaql_data_service::*;
use teaql_runtime::{GraphNode,GraphOperation,GraphMutationPlan,RuntimeModule,EntityDataService,InternalIdGenerator,RuntimeError};
#[path="../../../rust_values/src/fixture_value.rs"]mod fixture_value;
fn record(j:&J)->BTreeMap<String,Value>{j.as_object().unwrap().iter().map(|(k,v)|(k.clone(),fixture_value::value(v))).collect()}
fn node(j:&J)->GraphNode{let mut n=GraphNode::new(j["entity"].as_str().unwrap()).operation([GraphOperation::Upsert,GraphOperation::Create,GraphOperation::Reference,GraphOperation::Remove][j["operation"].as_u64().unwrap() as usize]);n.values=record(&j["values"]).into();n.dirty_fields=j["dirty"].as_array().map(|v|v.iter().map(|s|s.as_str().unwrap().into()).collect());n.original_values=j["old"].as_object().map(|_|record(&j["old"]).into());if let Some(s)=j["comment"].as_str(){n.set_comment(s)}for(k,v)in j["relations"].as_object().unwrap(){n.relations.insert(k.clone(),v.as_array().unwrap().iter().map(node).collect());}n}
fn record_out(values:&BTreeMap<String,Value>,before:i64,after:i64)->J{json!(values.iter().map(|(k,v)|{let text=match v{Value::Timestamp(t)if t.as_millis()>=before&&t.as_millis()<=after=>"Timestamp(<current>)".into(),_=>format!("{v:?}")};(k.clone(),text)}).collect::<BTreeMap<_,_>>())}
fn node_out(n:&GraphNode,before:i64,after:i64)->J{json!({"entity":n.entity,"values":record_out(&n.values,before,after),"operation":format!("{:?}",n.operation),"dirty":n.dirty_fields,"old":n.original_values.as_ref().map(|v|record_out(v,before,after)),"comment":n.comment,"relations":n.relations.iter().map(|(k,v)|(k.clone(),v.iter().map(|n|node_out(n,before,after)).collect::<Vec<_>>())).collect::<BTreeMap<_,_>>()})}
fn trace_out(v:&[TraceNode])->J{json!(v.iter().map(|n|json!({"entity":n.entity_type,"comment":n.comment,"id":n.entity_id,"kind":n.kind as u8})).collect::<Vec<_>>())}
fn plan_out(p:&GraphMutationPlan,before:i64,after:i64)->J{json!({"root":node_out(p.planned_root.as_ref().unwrap(),before,after),"next":p.next_item_index,"items":p.items.iter().map(|i|{let mut indices=Vec::new();let mut t=i.scope_token.as_ref();while let Some(token)=t{indices.push(token.node_index);t=token.parent.as_ref();}json!({"entity":i.entity,"kind":i.kind as u8,"index":i.item_index,"values":record_out(&i.values,before,after),"fields":i.update_fields,"old":i.old_values.as_ref().map(|v|record_out(v,before,after)),"trace":trace_out(&i.scope_token.as_ref().map(|t|t.recover_trace_chain()).unwrap_or_default()),"token_indices":indices})}).collect::<Vec<_>>(),"batches":p.batches.iter().map(|b|json!({"entity":b.entity,"kind":b.kind as u8,"fields":b.update_fields,"indices":b.items.iter().map(|i|i.item_index).collect::<Vec<_>>()})).collect::<Vec<_>>(),"visited":p.visited_nodes.iter().cloned().collect::<BTreeSet<_>>()})}
struct Generator{fail:bool,next:Arc<AtomicU64>}
impl InternalIdGenerator for Generator{fn generate_id(&self,_:&str)->Result<u64,RuntimeError>{if self.fail{Err(RuntimeError::IdGeneration("ID failed".into()))}else{Ok(self.next.fetch_add(1,Ordering::Relaxed))}}}
struct Mock{requests:Arc<Mutex<Vec<J>>>,exists:bool,failure:String}
impl DataServiceExecutor for Mock{type Error=io::Error;fn capabilities(&self)->DataServiceCapabilities{DataServiceCapabilities::default()}}
impl QueryExecutor for Mock{async fn query(&self,r:QueryRequest)->Result<QueryResult,Self::Error>{self.requests.lock().unwrap().push(json!({"entity":r.query.entity,"filter":r.query.filter.as_ref().map(|v|format!("{v:?}")),"trace":trace_out(&r.query.trace_chain),"request_trace":trace_out(&r.trace_chain),"comment":r.query.comment}));if r.query.entity==self.failure{return Err(io::Error::other("lookup failed"))}Ok(QueryResult{rows:if self.exists{vec![CompactRow::from_map(BTreeMap::from([("id".into(),Value::U64(999))]))]}else{vec![]},metadata:ExecutionMetadata::unrecorded_query(if self.exists{1}else{0})})}}
impl MutationExecutor for Mock{async fn mutate(&self,_:MutationRequest)->Result<MutationResult,Self::Error>{panic!("planning must not mutate")}}
struct NoWake;impl Wake for NoWake{fn wake(self:Arc<Self>){}}
fn wait<F:Future>(f:F)->F::Output{let mut f=std::pin::pin!(f);let w=Waker::from(Arc::new(NoWake));let mut cx=Context::from_waker(&w);loop{if let Poll::Ready(v)=f.as_mut().poll(&mut cx){return v}}}
fn evaluate(j:J)->J{let mut m=RuntimeModule::new();for info in j["descriptors"].as_array().unwrap(){let mut d=EntityDescriptor::new(info["name"].as_str().unwrap());let id=info["id"].as_str().unwrap();if !id.is_empty(){d=d.property(PropertyDescriptor::new(id,DataType::U64).id())}if info["version"]==true{d=d.property(PropertyDescriptor::new("version",DataType::I64).version())}d=d.property(PropertyDescriptor::new("name",DataType::Text));if info["timestamps"]==true{d=d.property(PropertyDescriptor::new("create_time",DataType::Timestamp)).property(PropertyDescriptor::new("update_time",DataType::Timestamp))}for r in info["relations"].as_array().unwrap(){d=d.relation(RelationDescriptor::new(r["name"].as_str().unwrap(),r["target"].as_str().unwrap()).local_key("id").foreign_key("parent_id").many())}m=m.descriptor(d);}
 let mut c=m.into_context();c.disable_sql_log();c.set_user_identifier("fixture");let next=Arc::new(AtomicU64::new(100));c.set_internal_id_generator(Generator{fail:j["id_fail"]==true,next:next.clone()});let requests=Arc::new(Mutex::new(Vec::new()));let e=Mock{requests:requests.clone(),exists:j["exists"]==true,failure:j["fail_entity"].as_str().unwrap().into()};let service=EntityDataService::for_executor(&c,j["service"].as_str().unwrap(),&e);let before=teaql_core::time::Timestamp::now().as_millis();let result=wait(service.plan_graph(node(&j["node"])));let after=teaql_core::time::Timestamp::now().as_millis();let mut out=match result{Ok(p)=>json!({"plan":plan_out(&p,before,after)}),Err(e)=>json!({"error":e.to_string()})};out["requests"]=json!(*requests.lock().unwrap());out["next_id"]=json!(next.load(Ordering::Relaxed));out}
fn main(){unsafe{std::env::set_var("TEAQL_LOG_ENDPOINT","off");}for line in io::stdin().lock().lines(){println!("{}",evaluate(serde_json::from_str(&line.unwrap()).unwrap()));}}
